/**
 * A scrolling conversation log that follows the newest turn (`design/components/chat-thread.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/chat-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  agentMember,
  cell,
  elementRef,
  followEnd,
  jumpToEnd,
  mountEffect,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/chat-thread.module.css'
import { Button, type ButtonProps } from '../controls/Button'

export interface ChatThreadMessages {
  jumpToLatest: string
}

/** A scrolling conversation log that follows the newest turn: the inputs it takes, by the React member's prop names. */
export interface ChatThreadProps {
  /**
   * The log's accessible name, such as "Conversation" in the app's language.
   */
  label: string
  /**
   * The thread's only built-in text (generic English default), which localized hosts replace.
   */
  messages?: ChatThreadMessages
  /**
   * Whether a reply is arriving, which sets `aria-busy` on the log.
   */
  streaming?: boolean
}

/** A scrolling conversation log that follows the newest turn. */
@Component({
  selector: 'pm-chat-thread',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate, Button],
  // prettier-ignore
  template: `<ng-template pmSlot="empty" [pmSlotOf]="$"><ng-content select="[slot=empty]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- root -->
<div
[attr.class]="e1()"
[attr.data-state]="e2()"
[attr.data-streaming]="e3()"
data-member="chat-thread"
><!-- viewport -->
<div
[attr.class]="e4()"
data-chat-thread-part="viewport"
role="log"
[attr.aria-label]="e5()"
aria-relevant="additions"
[attr.aria-busy]="e6()"
[attr.tabindex]="e7()"
[pmRef]="viewport"
>@if (e8()) {<!-- empty -->
<div
[attr.class]="e9()"
><ng-container [pmSlotOutlet]="'empty'" [pmSlotOf]="$" /></div>} @else {<!-- list -->
<div
[attr.class]="e10()"
[pmRef]="list"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>}</div>
<!-- jump -->
<div
[attr.class]="e11()"
[pmRef]="jump"
><pm-button
variant="outline"
tone="neutral"
size="sm"
icon="down"
[label]="e12()"
(click)="h1()"
></pm-button></div></div>`,
})
export class ChatThread {
  /**
   * The log's accessible name, such as "Conversation" in the app's language.
   */
  readonly label = input.required<ChatThreadProps['label']>()
  /**
   * The thread's only built-in text (generic English default), which localized hosts replace.
   */
  readonly messages = input<
    Exclude<ChatThreadProps['messages'], undefined>,
    ChatThreadProps['messages']
  >((() => ({ jumpToLatest: 'Jump to latest' }))(), {
    transform: (value: ChatThreadProps['messages']) =>
      value === undefined ? (() => ({ jumpToLatest: 'Jump to latest' }))() : value,
  })
  /**
   * Whether a reply is arriving, which sets `aria-busy` on the log.
   */
  readonly streaming = input<
    Exclude<ChatThreadProps['streaming'], undefined>,
    ChatThreadProps['streaming']
  >(false, {
    transform: (value: ChatThreadProps['streaming']) => (value === undefined ? false : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: {
      label: () => this.label(),
      messages: () => this.messages(),
      streaming: () => this.streaming(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly detached = cell(() => false)
  protected readonly overflowing = cell(() => false)
  protected readonly jump = elementRef<HTMLElement>()
  protected readonly list = elementRef<HTMLElement>()
  protected readonly viewport = elementRef<HTMLElement>()
  private release1: (() => void) | undefined
  private release2: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    watchEffect(
      () => this.list.value,
      () => this.effect1(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.detached.value ? 'detached' : undefined
  }

  protected e3() {
    return this.$p.streaming ? '' : undefined
  }

  protected e4() {
    return styles.viewport
  }

  protected e5() {
    return this.$p.label
  }

  protected e6() {
    return this.$p.streaming ? true : undefined
  }

  protected e7() {
    return this.overflowing.value ? '0' : undefined
  }

  protected e8() {
    return this.$.slotted('default').count === 0
  }

  protected e9() {
    if (!(this.$.slotted('default').count === 0)) return undefined as never
    return styles.empty
  }

  protected e10() {
    if (this.$.slotted('default').count === 0) return undefined as never
    return styles.list
  }

  protected e11() {
    return styles.jump
  }

  protected e12(): ButtonProps['label'] {
    return this.$p.messages.jumpToLatest
  }

  protected h1(): void {
    jumpToEnd(this.viewport.value)
  }

  private effect1(): void {
    this.release1?.()
    const ran = followEnd(this.viewport.value, this.list.value, (state) => {
      this.detached.value = state.detached
      this.overflowing.value = state.overflowing
    })
    this.release1 = () => {
      ran()
    }
  }

  private effect2(): void {
    this.release2?.()
    const ran = agentMember({
      member: 'ChatThread',
      element: () => this.viewport.value,
      state: () => ({ streaming: this.$p.streaming }),
      actions: {},
      withholds: () => this.jump.value,
    })
    this.release2 = () => {
      ran()
    }
  }
}
